    "zgh": "ⵙⵉⵍ ⵖⴼ ⴰⴽⴽⵯ ⵉⵙⴽⵯⴼⴰⵏ ⴷ ⵉⵎⴰⵍⴰⵙⵏ ⴷ ⵜⵣⵣⵓⵍⴳⴰⵢⵉⵏ ⵉⵜⵜⵓⴰⵎⴰⵔⵏ ⵏ ⵜⵎⵣⴳⵉⴷⴰ."
