    "zgh": "ⵢⴰⵜ ⵜⴰⴼⵓⵔⵎⵓⵍⴰ ⵜⵓⵏⵖⵉⴱⵜ ⵉ ⵜⵓⵟⵟⵓⴱⵜ ⵏ ⵓⵙⵏⵛⵎⵎⴽ ⴷ ⵜⵎⵣⴳⵉⴷⴰ, ⵍⵍⵉ ⵉⵥⴹⴰⵕⵏ ⵉⵏⴼⵓⵔⵎⴰⵙⵏ ⵉⵣⴰⵍⴰⵏⵏ ⴷ ⵉⵙⴼⵉⵡⵏ ⵉⴷⴷⵓⵔⴰⵏ."
