    "zgh": "ⴰⴽⴽⵯ ⵉⵣⵔⴼⴰⵏ ⴷ ⵉⵡⴰⵍⵉⵏ ⵏ ⵉⵏⴰⵎⵓⵔⵏ ⵏ ⵜⵎⵣⴳⵉⴷⴰ, ⴷ ⵉⵏⵓⵎⴰⴽ ⵏ ⵜⵓⵙⵏⵓⵏⵙ ⵍⵍⵉ ⵉⵙⵙⵉⵖⵉⵎⵏ ⴰⵙⵡⵓⵔⵢ ⵏ ⵜⵎⵣⴳⵉⴷⴰ."
