    "zgh": "ⵡⴰⵜⵉⵇⴰ ⵏ ⵍⵉⵍⵜⵉⵣⴰⵎ ⵙ ⵛⵔⵓⵟ ⴷ ⵇⵡⴰⵏⵉⵏ ⵏ ⵜⵎⵣⴳⵉⴷⴰ ⵏⵏⴰ ⵉⵍⵍⴰⵏ ⴼ ⴽⵓ ⴰⵎⵏⵙ ⴰⴷ ⵉⵜⵙⵏ ⵉⵣⵎⵎⴰⵍ ⵏⵏⵙ ⴷ ⴰⴷ ⵉⵍⵜⵉⵣⵎ ⵙ ⵉⵣⵎⵎⴰⵍ ⵏⵏⵙ"
