    "en": "You can download all membership documents in a single compressed file to make registration easier and review all documents at once.",
    "es": "Puedes descargar todos los documentos de afiliación en un solo archivo comprimido para facilitar el registro y consultar todos los documentos de una sola vez.",
    "zgh": "ⵜⵣⵎⵔⴷ ⴰⴷ ⵜⵣⴷⵎⴷ ⵉⵎⴰⵙⵙⵓⵏ ⴰⴽⴽⵯ ⵏ ⵓⵏⵙⵙⵓⵎⵔ ⴳ ⵢⴰⵏ ⵓⴼⵓⵢⵍⵓ ⵉⵣⴷⴼⵏ ⵉ ⵜⵓⵙⵙⵏⴰ ⵏ ⵜⵙⴽⵍⴰ ⴷ ⵓⵥⵔ ⵏ ⵉⵎⴰⵙⵙⵓⵏ ⴰⴽⴽⵯ ⴳ ⵢⴰⵜ ⵜⵉⴽⴽⵍⵜ ⵢⵉⵡⵏⵜ"
