    "en": "Our activities | Moroccan Association of Research and Exploration Enthusiasts",
    "es": "Nuestras actividades | Asociación Marroquí de Aficionados a la Investigación y la Exploración",
    "zgh": "ⵉⵎⴰⵍⴰⵙⵏ ⵏⵏⵖ | ⵜⴰⵎⵣⴳⵉⴷⴰ ⵜⴰⵎⵖⵔⵉⴱⵉⵢⵜ ⵏ ⵉⵏⵛⵎⵎⴰⴽⵏ ⵏ ⵓⵎⴰⴷⴷⵓⵔ ⴷ ⵜⵎⵣⵣⴰⵍⵍⵉⵜ"
