  "AssociationDetectionCentre | شريك الجمعية | الجمعية المغربية لهواة البحث والاستكشاف": {
    "fr": "AssociationDetectionCentre | Partenaire de l'association | Association marocaine des passionnés de recherche et d'exploration",
    "en": "AssociationDetectionCentre | Association partner | Moroccan Association of Research and Exploration Enthusiasts",
    "es": "AssociationDetectionCentre | Socio de la asociación | Asociación Marroquí de Aficionados a la Investigación y la Exploración",
    "zgh": "AssociationDetectionCentre | ⴰⵎⵢⴰⵡⴰⵙ ⵏ ⵜⵎⵣⴳⵉⴷⴰ | ⵜⴰⵎⵣⴳⵉⴷⴰ ⵜⴰⵎⵖⵔⵉⴱⵉⵢⵜ ⵏ ⵉⵏⵛⵎⵎⴰⴽⵏ ⵏ ⵓⵎⴰⴷⴷⵓⵔ ⴷ ⵜⵎⵣⵣⴰⵍⵍⵉⵜ"
  },
  "شريك استراتيجي للجمعية المغربية لهواة البحث والاستكشاف، مركز متخصص في الكشف والتنقيب والتدريب على استخدام أجهزة الاستكشاف.": {
    "fr": "Partenaire stratégique de l'association marocaine des passionnés de recherche et d'exploration, un centre spécialisé dans la détection, la prospection et la formation à l'utilisation des appareils d'exploration.",
    "en": "A strategic partner of the Moroccan Association of Research and Exploration Enthusiasts, a centre specialized in detection, prospecting and training on the use of exploration devices.",
    "es": "Socio estratégico de la Asociación Marroquí de Aficionados a la Investigación y la Exploración, un centro especializado en detección, prospección y formación en el uso de dispositivos de exploración.",
    "zgh": "ⴰⵎⵢⴰⵡⴰⵙ ⴰⵙⵜⵔⴰⵜⵉⵊⵉ ⵏ ⵜⵎⵣⴳⵉⴷⴰ ⵜⴰⵎⵖⵔⵉⴱⵉⵢⵜ ⵏ ⵉⵏⵛⵎⵎⴰⴽⵏ ⵏ ⵓⵎⴰⴷⴷⵓⵔ ⴷ ⵜⵎⵣⵣⴰⵍⵍⵉⵜ, ⴰⵎⵎⴰⵙ ⵉⵣⴷⴳⵏ ⴳ ⵓⵎⵔⴽⵙ, ⵓⵙⵎⵓⵜⵜⵢ ⴷ ⵜⵓⵙⵙⵏⴰ ⵏ ⵉⵙⵓⵎⴰⵔ ⵏ ⵜⵎⵣⵣⴰⵍⵍⵉⵜ."
  },
  "عن AssociationDetectionCentre": {
    "fr": "À propos d'AssociationDetectionCentre",
    "en": "About AssociationDetectionCentre",
    "es": "Acerca de AssociationDetectionCentre",
    "zgh": "ⵅⴼ AssociationDetectionCentre"
  },
  "AssociationDetectionCentre هو مركز متخصص في الكشف والتنقيب والتدريب على استخدام أحدث أجهزة الاستكشاف. يقدم المركز دورات تكوينية وورشات عملية لتطوير مهارات المنقبين والمستكشفين.": {
    "fr": "AssociationDetectionCentre est un centre spécialisé dans la détection, la prospection et la formation à l'utilisation des appareils d'exploration les plus récents. Le centre propose des cours de formation et des ateliers pratiques pour développer les compétences des prospecteurs et des explorateurs.",
    "en": "AssociationDetectionCentre is a centre specialized in detection, prospecting and training on the use of the latest exploration devices. The centre offers training courses and hands-on workshops to develop the skills of prospectors and explorers.",
    "es": "AssociationDetectionCentre es un centro especializado en detección, prospección y formación en el uso de los dispositivos de exploración más recientes. El centro ofrece cursos de formación y talleres prácticos para desarrollar las habilidades de prospectores y exploradores.",
    "zgh": "AssociationDetectionCentre ⵉⴳⴰ ⴰⵎⵎⴰⵙ ⵉⵣⴷⴳⵏ ⴳ ⵓⵎⵔⴽⵙ, ⵓⵙⵎⵓⵜⵜⵢ ⴷ ⵜⵓⵙⵙⵏⴰ ⵏ ⵉⵙⵓⵎⴰⵔ ⵉⵏⴳⴳⵓⵔⴰ ⵏ ⵜⵎⵣⵣⴰⵍⵍⵉⵜ. ⴰⵔ ⵉⵙⵎⵉⵔ ⵓⵎⵎⴰⵙ ⵜⵉⵏⵎⵍⵉⵏ ⴷ ⵜⵉⵙⴳⴳⵯⴰⵎⵉⵏ ⵜⵉⵎⵏⴰⴹⵉⵏ ⵉ ⵓⵏⴼⵍ ⵏ ⵜⵉⵏⴳⴰⵢⵉⵏ ⵏ ⵉⵏⵙⵎⵓⵜⵜⵢⵏ ⴷ ⵉⵏⵛⵎⵎⴰⴽⵏ."
  },
  "نعمل مع الجمعية المغربية لهواة البحث والاستكشاف في إطار شراكة استراتيجية تهدف إلى توفير التكوين والتدريب المتخصص لأعضاء الجمعية في مجال استخدام أجهزة الكشف والتنقيب.": {
    "fr": "Nous collaborons avec l'association marocaine des passionnés de recherche et d'exploration dans le cadre d'un partenariat stratégique visant à offrir une formation spécialisée aux membres de l'association dans l'utilisation des appareils de détection et de prospection.",
    "en": "We work with the Moroccan Association of Research and Exploration Enthusiasts within a strategic partnership aimed at providing specialized training to the association's members in the use of detection and prospecting devices.",
    "es": "Trabajamos con la Asociación Marroquí de Aficionados a la Investigación y la Exploración en el marco de una alianza estratégica destinada a ofrecer formación especializada a los miembros de la asociación en el uso de dispositivos de detección y prospección.",
    "zgh": "ⴰⵔ ⵏⴳ ⵜⴰⵡⵓⵔⵉ ⴷ ⵜⵎⵣⴳⵉⴷⴰ ⵜⴰⵎⵖⵔⵉⴱⵉⵢⵜ ⵏ ⵉⵏⵛⵎⵎⴰⴽⵏ ⵏ ⵓⵎⴰⴷⴷⵓⵔ ⴷ ⵜⵎⵣⵣⴰⵍⵍⵉⵜ ⴳ ⵓⵎⵢⴰⵡⴰⵙ ⴰⵙⵜⵔⴰⵜⵉⵊⵉ ⵉⵏⵓⵎⴰⵏ ⵉ ⵜⵎⵉⵏⵉ ⵏ ⵜⵓⵙⵙⵏⴰ ⵜⴰⵣⴷⴳⵏⵜ ⵉ ⵉⵏⴰⵎⵓⵔⵏ ⵏ ⵜⵎⵣⴳⵉⴷⴰ ⴳ ⵓⵙⵙⵎⵔⵙ ⵏ ⵉⵙⵓⵎⴰⵔ ⵏ ⵓⵎⵔⴽⵙ ⴷ ⵓⵙⵎⵓⵜⵜⵢ."
  },
