  "شريك رئيسي": {
    "fr": "Partenaire principal",
    "en": "Main partner",
    "es": "Socio principal",
    "zgh": "ⴰⵎⵢⴰⵡⴰⵙ ⴰⵎⵓⵏⵉ"
  },
  "شريك رئيسي للجمعية المغربية لهواة البحث والاستكشاف، منظمة مغربية للتنمية الاجتماعية والتضامن تعمل على دعم المبادرات المجتمعية.": {
    "fr": "Partenaire principal de l'association marocaine des passionnés de recherche et d'exploration, une organisation marocaine de développement social et de solidarité qui soutient les initiatives communautaires.",
    "en": "A main partner of the Moroccan Association of Research and Exploration Enthusiasts, a Moroccan organization for social development and solidarity that supports community initiatives.",
    "es": "Socio principal de la Asociación Marroquí de Aficionados a la Investigación y la Exploración, una organización marroquí de desarrollo social y solidaridad que apoya las iniciativas comunitarias.",
    "zgh": "ⴰⵎⵢⴰⵡⴰⵙ ⴰⵎⵓⵏⵉ ⵏ ⵜⵎⵣⴳⵉⴷⴰ ⵜⴰⵎⵖⵔⵉⴱⵉⵢⵜ ⵏ ⵉⵏⵛⵎⵎⴰⴽⵏ ⵏ ⵓⵎⴰⴷⴷⵓⵔ ⴷ ⵜⵎⵣⵣⴰⵍⵍⵉⵜ, ⵢⴰⵜ ⵜⵎⵓⵏⵜ ⵜⴰⵎⵖⵔⵉⴱⵉⵢⵜ ⵏ ⵓⵏⴼⵍ ⴰⴳⵔⴰⵡⴰⵏ ⴷ ⵓⵎⵢⴰⵡⴰⵙ ⵜⵓⵔ ⵉ ⵓⵙⴳⵎⵎⵓⵢ ⵏ ⵜⵉⵖⵔⵡⵉⵏ ⵜⵉⴳⵔⴰⵡⴰⵏⵉⵏ."
  },
  "عن OMSDS": {
    "fr": "À propos d'OMSDS",
    "en": "About OMSDS",
    "es": "Acerca de OMSDS",
    "zgh": "ⵅⴼ OMSDS"
  },
  "OMSDS هي منظمة مغربية للتنمية الاجتماعية والتضامن، تعمل على دعم وتمكين المجتمع المدني من خلال برامج تنموية واجتماعية متنوعة تستهدف الفئات المحتاجة.": {
    "fr": "OMSDS est une organisation marocaine de développement social et de solidarité qui œuvre pour soutenir et autonomiser la société civile grâce à des programmes de développement et sociaux variés destinés aux personnes dans le besoin.",
    "en": "OMSDS is a Moroccan organization for social development and solidarity, working to support and empower civil society through a variety of development and social programs targeting those in need.",
    "es": "OMSDS es una organización marroquí de desarrollo social y solidaridad que trabaja para apoyar y empoderar a la sociedad civil mediante programas de desarrollo y sociales de diversa índole dirigidos a quienes más lo necesitan.",
    "zgh": "OMSDS ⵜⴳⴰ ⵢⴰⵜ ⵜⵎⵓⵏⵜ ⵜⴰⵎⵖⵔⵉⴱⵉⵢⵜ ⵏ ⵓⵏⴼⵍ ⴰⴳⵔⴰⵡⴰⵏ ⴷ ⵓⵎⵢⴰⵡⴰⵙ, ⵜⵓⵔ ⴼ ⵓⵙⴳⵎⵎⵓⵢ ⴷ ⵓⵏⴼⵍ ⵏ ⵉⵖⴼ ⵏ ⵜⴳⵔⴰⵡⵜ ⴰⵙⵎⴰⵎⴽⴰⵏ ⵙ ⵉⵓⵎⴰⵏⵉⵏ ⵏ ⵓⵏⴼⵍ ⴷ ⵉⵙⵏⴼⵍⵓⵍⵏ ⵉⵎⵥⵍⴰⵏ ⵉⵏⵓⵎⴰⵏ ⵖⵔ ⵜⴰⵡⴰ ⵜⵓⵙⵙⵏⵜ ⵜⴰⵎⴰⵏⵏⴰⵡⵜ."
  },
  "نعمل مع الجمعية المغربية لهواة البحث والاستكشاف في إطار شراكة مجتمعية تهدف إلى دعم الأنشطة الاجتماعية والتطوعية وتعزيز قيم التضامن والتكافل.": {
    "fr": "Nous collaborons avec l'association marocaine des passionnés de recherche et d'exploration dans le cadre d'un partenariat communautaire visant à soutenir les activités sociales et bénévoles et à renforcer les valeurs de solidarité et d'entraide.",
    "en": "We work with the Moroccan Association of Research and Exploration Enthusiasts within a community partnership aimed at supporting social and volunteer activities and strengthening the values of solidarity and mutual support.",
    "es": "Trabajamos con la Asociación Marroquí de Aficionados a la Investigación y la Exploración en el marco de una alianza comunitaria destinada a apoyar las actividades sociales y voluntarias y a reforzar los valores de solidaridad y ayuda mutua.",
    "zgh": "ⴰⵔ ⵏⴳ ⵜⴰⵡⵓⵔⵉ ⴷ ⵜⵎⵣⴳⵉⴷⴰ ⵜⴰⵎⵖⵔⵉⴱⵉⵢⵜ ⵏ ⵉⵏⵛⵎⵎⴰⴽⵏ ⵏ ⵓⵎⴰⴷⴷⵓⵔ ⴷ ⵜⵎⵣⵣⴰⵍⵍⵉⵜ ⴳ ⵓⵎⵢⴰⵡⴰⵙ ⴰⴳⵔⴰⵡⴰⵏ ⵉⵏⵓⵎⴰⵏ ⵉ ⵓⵙⴳⵎⵎⵓⵢ ⵏ ⵉⵎⴰⵍⴰⵙⵏ ⵉⵏⴰⵎⵓⵏⵏ ⴷ ⵉⵏⵙⵜⵉⵡⵉⵢⵏ ⴷ ⵓⵣⴷⴰⵢ ⵏ ⵉⵣⵔⴼⴰⵏ ⵏ ⵓⵎⵢⴰⵡⴰⵙ ⴷ ⵜⵉⵎⵎⴰⵍⴰ."
  },
