  "شريك دولي": {
    "fr": "Partenaire international",
    "en": "International partner",
    "es": "Socio internacional",
    "zgh": "ⴰⵎⵢⴰⵡⴰⵙ ⴰⴳⵔⴰⵡⴰⵏ"
  },
  "شريك دولي للجمعية المغربية لهواة البحث والاستكشاف، متخصص في الحلول التقنية والأمنية المتطورة على المستوى الدولي.": {
    "fr": "Partenaire international de l'association marocaine des passionnés de recherche et d'exploration, spécialisé dans les solutions techniques et de sécurité avancées au niveau international.",
    "en": "An international partner of the Moroccan Association of Research and Exploration Enthusiasts, specialized in advanced technical and security solutions at the international level.",
    "es": "Socio internacional de la Asociación Marroquí de Aficionados a la Investigación y la Exploración, especializado en soluciones técnicas y de seguridad avanzadas a nivel internacional.",
    "zgh": "ⴰⵎⵢⴰⵡⴰⵙ ⴰⴳⵔⴰⵡⴰⵏ ⵏ ⵜⵎⵣⴳⵉⴷⴰ ⵜⴰⵎⵖⵔⵉⴱⵉⵢⵜ ⵏ ⵉⵏⵛⵎⵎⴰⴽⵏ ⵏ ⵓⵎⴰⴷⴷⵓⵔ ⴷ ⵜⵎⵣⵣⴰⵍⵍⵉⵜ, ⵉⵣⴷⴳⵏ ⴳ ⵉⴼⵔⵉⵙⵏ ⵉⵟⵟⴰⵙⵏⵏ ⴷ ⵉⵎⵎⵙⵜⵉⵏ ⵉⵜⵜⵢⴰⵡⵏ ⴳ ⵓⵏⵙⵉⴱ ⴰⴳⵔⴰⵡⴰⵏ."
  },
  "عن SENOTEC": {
    "fr": "À propos de SENOTEC",
    "en": "About SENOTEC",
    "es": "Acerca de SENOTEC",
    "zgh": "ⵅⴼ SENOTEC"
  },
  "SENOTEC هي شركة دولية متخصصة في تقديم الحلول التقنية والأمنية المتطورة. تمتلك الشركة خبرة واسعة في مجال أنظمة المراقبة والحماية الإلكترونية للمؤسسات والمنشآت.": {
    "fr": "SENOTEC est une entreprise internationale spécialisée dans la fourniture de solutions techniques et de sécurité avancées. L'entreprise possède une vaste expérience dans le domaine des systèmes de surveillance et de protection électronique des institutions et des installations.",
    "en": "SENOTEC is an international company specialized in providing advanced technical and security solutions. The company has extensive experience in surveillance systems and electronic protection for institutions and facilities.",
    "es": "SENOTEC es una empresa internacional especializada en ofrecer soluciones técnicas y de seguridad avanzadas. La empresa cuenta con amplia experiencia en sistemas de vigilancia y protección electrónica para instituciones e instalaciones.",
    "zgh": "SENOTEC ⵜⴳⴰ ⵢⴰⵜ ⵜⵎⵙⵓⵔⵜ ⵜⴰⴳⵔⴰⵡⴰⵏⵜ ⵜⵣⴷⴳⵏⵜ ⴳ ⵜⵎⵉⵏⵉ ⵏ ⵉⴼⵔⵉⵙⵏ ⵉⵟⵟⴰⵙⵏⵏ ⴷ ⵉⵎⵎⵙⵜⵉⵏ ⵉⵜⵜⵢⴰⵡⵏ. ⵜⵍⵍⴰ ⵜⵖⴰⵔⴰⵙⵜ ⵜⴰⵖⵔⵉⵡⵉⵢⵜ ⵜⴰⵖⵣⵣⴰⴼⵜ ⴳ ⵉⵏⵣⵎⴰⵎⵏ ⵏ ⵓⵎⵏⵉⴳ ⴷ ⵓⵎⵎⵙⵜⵉ ⵉⵎⵓⵏⵜⵔⵏ ⵏ ⵜⵎⵓⵏⵜⵉⵏ ⴷ ⵜⵎⵓⴽⵔⵉⵙⵉⵏ."
  },
  "نعمل مع الجمعية المغربية لهواة البحث والاستكشاف في إطار شراكة دولية تهدف إلى تعزيز الأمن والسلامة في الأنشطة الميدانية والاستكشافية.": {
    "fr": "Nous collaborons avec l'association marocaine des passionnés de recherche et d'exploration dans le cadre d'un partenariat international visant à renforcer la sécurité et la sûreté dans les activités de terrain et d'exploration.",
    "en": "We work with the Moroccan Association of Research and Exploration Enthusiasts within an international partnership aimed at enhancing security and safety in field and exploration activities.",
    "es": "Trabajamos con la Asociación Marroquí de Aficionados a la Investigación y la Exploración en el marco de una alianza internacional destinada a reforzar la seguridad en las actividades de campo y exploración.",
    "zgh": "ⴰⵔ ⵏⴳ ⵜⴰⵡⵓⵔⵉ ⴷ ⵜⵎⵣⴳⵉⴷⴰ ⵜⴰⵎⵖⵔⵉⴱⵉⵢⵜ ⵏ ⵉⵏⵛⵎⵎⴰⴽⵏ ⵏ ⵓⵎⴰⴷⴷⵓⵔ ⴷ ⵜⵎⵣⵣⴰⵍⵍⵉⵜ ⴳ ⵓⵎⵢⴰⵡⴰⵙ ⴰⴳⵔⴰⵡⴰⵏ ⵉⵏⵓⵎⴰⵏ ⵉ ⵓⵣⴷⴰⵢ ⵏ ⵜⵉⵏⴳⵍⴰ ⴷ ⵜⴰⵎⵓⵜⵜⵔⵜ ⴳ ⵉⵎⴰⵍⴰⵙⵏ ⵉⵎⵓⴷⵔⴰⵏⵏ ⴷ ⵉⵏⵛⵎⵎⴰⴽⵏ."
  },
