    "zgh": "ⵜⴰⵎ ⵉⵏⴰⵎⵓⵏⵙⵏ ⵉⴷⵙⵏⵏ ⵏⵏⴰ ⵉⵙⵓⵇⵇⵍⵏ ⵉⵎⴰⵏⵏⴰⵢⵏ ⵏⵏⵖ ⵖⴰⵔ ⵢⴰⵏ ⵓⵏⴰⵢⵓ ⴰⵙⵙⴰⵏ ⵉⵎⵥⵍⵉⵏ ⴳ ⴽⵓ ⵍⵍⵉ ⵏⵙⴽⴰⵔ"
