  "جهة طنجة - تطوان - الحسيمة | الفروع الجهوية | الجمعية المغربية لهواة البحث والاستكشاف": {
    "fr": "Région de Tanger - Tétouan - Al Hoceïma | Branches régionales | Association Marocaine des Amateurs de Recherche et d'Exploration",
    "en": "Tangier - Tetouan - Al Hoceima Region | Regional Branches | Moroccan Association of Research and Exploration Enthusiasts",
    "es": "Región de Tánger - Tetuán - Alhucemas | Sucursales regionales | Asociación Marroquí de Aficionados a la Investigación y la Exploración",
    "zgh": "ⵜⴰⵎⵏⴰⴹⵜ ⵏ ⵟⵟⴰⵏⵊⴰ - ⵜⵉⵟⵟⴰⵡⵉⵏ - ⵍⵃⵓⵙⵉⵎⴰ | ⵉⴼⵕⵄⵏ ⵉⵏⴰⴷⵓⵔⴰⵏ | ⵜⴰⵎⵣⴳⵉⴷⴰ ⵜⴰⵎⵖⵔⵉⴱⵉⵢⵜ ⵏ ⵉⵏⵎⵉⵏⴰⵢⵏ ⵏ ⵓⵎⴰⴷⴷⵓⵔ ⴷ ⵜⵎⵣⵣⴰⵍⵍⵉⵜ"
  },
  "فرع جهوي": {
    "fr": "Branche régionale",
    "en": "Regional branch",
    "es": "Sucursal regional",
    "zgh": "ⴰⴼⵕⵄ ⴰⵏⴰⴷⵓⵔ"
  },
  "الجهة الشمالية للمملكة المغربية، تطل على البحر الأبيض المتوسط والمحيط الأطلسي. تضم مدناً تاريخية وثقافية غنية، وهي بوابة المغرب نحو أوروبا.": {
    "fr": "La région septentrionale du Royaume du Maroc, ouverte sur la Méditerranée et l'océan Atlantique. Elle abrite des villes historiques et culturelles riches et constitue la porte du Maroc vers l'Europe.",
    "en": "The northern region of the Kingdom of Morocco, overlooking the Mediterranean Sea and the Atlantic Ocean. It contains rich historic and cultural cities and is Morocco's gateway to Europe.",
    "es": "La región septentrional del Reino de Marruecos, frente al mar Mediterráneo y el océano Atlántico. Alberga ciudades históricas y culturales muy ricas y es la puerta de Marruecos hacia Europa.",
    "zgh": "ⵜⴰⵎⵏⴰⴹⵜ ⵜⴰⵏⵉⴼⵜ ⵏ ⵜⴳⵍⴷⵉⵜ ⵜⴰⵎⵖⵔⵉⴱⵉⵢⵜ, ⵜⵣⵣⵔⵉ ⵖⴼ ⵉⵍⵍ ⴰⵎⵍⵍⴰⵍ ⴷ ⵓⴳⴰⵔⴰⵡ ⴰⵟⵍⴰⵙⵉ. ⵉⵍⵍⴰ ⴷⵉⴳⵙ ⵉⴷⵓⵔⴰⵏ ⵉⵎⵣⵔⴰⵡⵏ ⴷ ⵉⴷⵓⵙⵏ ⵙ ⵜⴰⵎⵓⵏⵜ, ⵜⴳⴰ ⵜⴰⴳⴳⵓⵔⵜ ⵏ ⵍⵎⵖⵔⵉⴱ ⵖⴰⵔ ⵜⵓⵔⵓⴼⵜ"
  },
  "نبذة عن الجهة": {
    "fr": "À propos de la région",
    "en": "About the region",
    "es": "Acerca de la región",
    "zgh": "ⵅⴼ ⵜⵎⵏⴰⴹⵜ"
  },
  "إحدى الجهات الإثنتي عشرة للمملكة المغربية": {
    "fr": "L'une des douze régions du Royaume du Maroc",
    "en": "One of the twelve regions of the Kingdom of Morocco",
    "es": "Una de las doce regiones del Reino de Marruecos",
    "zgh": "ⵢⴰⵜ ⵣⴳ ⵜⵎⵏⴰⴹⵉⵏ ⵜⵙⵏⴰⵜ ⵜⵏⴰⵎⵓⵔⵉⵏ ⵏ ⵜⴳⵍⴷⵉⵜ ⵜⴰⵎⵖⵔⵉⴱⵉⵢⵜ"
  },
  "تقع جهة طنجة - تطوان - الحسيمة في أقصى شمال المملكة المغربية، وتعتبر بوابة المغرب نحو أوروبا عبر مضيق جبل طارق. تتميز الجهة بتنوعها الجغرافي والثقافي الفريد، حيث تجمع بين السواحل المتوسطية والأطلسية والجبال الريفية الشاهقة. تضم الجهة مدناً تاريخية عريقة مثل طنجة وتطوان وشفشاون، وتعد مركزاً اقتصادياً وصناعياً مهماً بفضل ميناء طنجة المتوسط. كما تشتهر بتراثها الأندلسي وحرفها التقليدية ومطبخها المتنوع.": {
    "fr": "La région de Tanger - Tétouan - Al Hoceïma est située à l'extrême nord du Royaume du Maroc et constitue la porte du Maroc vers l'Europe par le détroit de Gibraltar. Elle se distingue par une diversité géographique et culturelle unique, mêlant littoraux méditerranéens et atlantiques et hautes montagnes du Rif. La région abrite de vieilles villes historiques telles que Tanger, Tétouan et Chefchaouen, et constitue un centre économique et industriel important grâce au port Tanger Med. Elle est également réputée pour son héritage andalou, son artisanat traditionnel et sa cuisine variée.",
    "en": "The Tangier - Tetouan - Al Hoceima region is located at the far north of the Kingdom of Morocco and is considered Morocco's gateway to Europe through the Strait of Gibraltar. The region is distinguished by its unique geographical and cultural diversity, combining Mediterranean and Atlantic coasts with the towering Rif mountains. It hosts ancient historic cities such as Tangier, Tetouan and Chefchaouen, and is an important economic and industrial centre thanks to the Tanger Med port. It is also famous for its Andalusian heritage, traditional crafts and varied cuisine.",
    "es": "La región de Tánger - Tetuán - Alhucemas se encuentra en el extremo norte del Reino de Marruecos y se considera la puerta de Marruecos hacia Europa a través del estrecho de Gibraltar. La región destaca por su singular diversidad geográfica y cultural, que combina costas mediterráneas y atlánticas con las imponentes montañas del Rif. Alberga antiguas ciudades históricas como Tánger, Tetuán y Chauen, y es un importante centro económico e industrial gracias al puerto de Tánger Med. También es famosa por su herencia andalusí, su artesanía tradicional y su variada gastronomía.",
    "zgh": "ⵜⴰⵎⵏⴰⴹⵜ ⵏ ⵟⵟⴰⵏⵊⴰ - ⵜⵉⵟⵟⴰⵡⵉⵏ - ⵍⵃⵓⵙⵉⵎⴰ ⵜⵍⵍⴰ ⴳ ⵜⴰⵖⵣⵓⵜ ⵏ ⵉⴳⴰⴼⴰⵢⵏ ⵏ ⵜⴳⵍⴷⵉⵜ ⵜⴰⵎⵖⵔⵉⴱⵉⵢⵜ, ⵜⵜⵓⵙⵙⴰⵏ ⵙ ⵜⴰⴳⴳⵓⵔⵜ ⵏ ⵍⵎⵖⵔⵉⴱ ⵖⴰⵔ ⵜⵓⵔⵓⴼⵜ ⵙ ⵎⴰⵏⵀⵇ ⵏ ⵊⴱⴰⵍ ⵟⴰⵕⵉⵇ. ⵜⵣⵎⵎⵉⵢ ⵜⵎⵏⴰⴹⵜ ⵙ ⵜⵎⵖⵓⵔⵉⵜ ⵜⴰⵊⵓⵖⵕⴰⴼⵉⵢⵜ ⴷ ⵜⴰⵏⴰⵎⵓⵏⵜ ⵜⴰⵎⵥⵍⵉⵜ, ⵜⵎⵓⵏ ⴷⵉⴳⵙ ⵜⵉⵖⵓⵔⴷⴰ ⵜⵉⵎⵍⵍⴰⵍⵉⵏ ⴷ ⵜⵉⵟⵍⴰⵙⵉⵢⵉⵏ ⴷ ⵉⴷⵔⵏ ⵉⵎⵇⵇⵕⴰⵏⵏ ⵏ ⵔⵔⵉⴼ. ⵜⴳⴰ ⵜⵎⵏⴰⴹⵜ ⵉⴷⵓⵔⴰⵏ ⵉⵎⵣⵔⴰⵡⵏ ⴰⵎ ⵟⵟⴰⵏⵊⴰ, ⵜⵉⵟⵟⴰⵡⵉⵏ ⴷ ⵛⴼⵛⴰⵡⵏ, ⵜⴳⴰ ⵢⴰⵏ ⵓⵎⵎⴰⵙ ⴰⴷⵎⵙⴰⵏ ⴷ ⴰⵎⴰⵏⵓ ⴳⵍⴰⵏ ⵙ ⵓⴱⵕⵥⵉⵎ ⵏ ⵟⵟⴰⵏⵊⴰ ⵎⴻⴷ. ⵜⵡⴰⵙⵙⴰⵏ ⵓⵍⴰ ⵙ ⵡⴰⴷⴷⵓⵔ ⵏⵏⵙ ⴰⵏⴷⵍⵓⵙⵉ, ⵜⵉⵍⴰⵍ ⵏⵏⵙ ⵜⵉⵎⵏⵣⴰ ⴷ ⵡⵓⵖⵓ ⵏⵏⵙ ⴰⵎⴽⵏⴰⵍ"
  },
