    "zgh": "ⵙⵙⵏ ⵅⴼ ⵜⵉⵎⴷⵉⵏⵉⵏ ⵏⵏⴰ ⵉⵍⵍⴰⵏ ⴷⴷⴰ ⵜⵎⵏⴰⴹⵜ ⵏ ⵟⵟⴰⵏⵊⴰ - ⵜⵉⵟⵟⴰⵡⵉⵏ - ⵍⵃⵓⵙⵉⵎⴰ."
