    "zgh": "ⵜⴰⵎⴷⵉⵏⵜ ⵜⴰⴳⵎⵓⵔⵜ ⵜⴰⵙⵜⵔⴰⵜⵉⵊⵉⵢⵜ ⵜⵣⵣⵔⵉ ⵖⴼ ⵎⴰⵏⵀⵇ ⵏ ⵊⴱⴰⵍ ⵟⴰⵕⵉⵇ, ⴰⵙⵎⵓⵏ ⵏ ⵜⵉⴷⵍⵙⵉⵡⵉⵏ ⵜⵉⵎⵍⵍⴰⵍⵉⵏ"
