  "فرع مدينة": {
    "fr": "Branche de la ville",
    "en": "City branch",
    "es": "Sucursal de la ciudad",
    "zgh": "ⴰⴼⵕⵄ ⵏ ⵜⵎⴷⵉⵏⵜ"
  },
  "مدينة ساحلية استراتيجية تطل على مضيق جبل طارق، ملتقى الحضارات المتوسطية والعالمية.": {
    "fr": "Une ville côtière stratégique donnant sur le détroit de Gibraltar, carrefour des civilisations méditerranéennes et mondiales.",
    "en": "A strategic coastal city overlooking the Strait of Gibraltar, a crossroads of Mediterranean and world civilizations.",
    "es": "Una ciudad costera estratégica frente al estrecho de Gibraltar, encrucijada de civilizaciones mediterráneas y mundiales.",
    "zgh": "ⵜⴰⵎⴷⵉⵏⵜ ⵜⴰⴳⵎⵓⵔⵜ ⵜⴰⵙⵜⵔⴰⵜⵉⵊⵉⵢⵜ ⵜⵣⵣⵔⵉ ⵖⴼ ⵎⴰⵏⵀⵇ ⵏ ⵊⴱⴰⵍ ⵟⴰⵕⵉⵇ, ⴰⵙⵎⵓⵏ ⵏ ⵜⵉⴷⵍⵙⵉⵡⵉⵏ ⵜⵉⵎⵍⵍⴰⵍⵉⵏ ⴷ ⵜⵉⵎⴰⵍⴰⵢⵉⵏ"
  },
  "انضم إلى الفرع": {
    "fr": "Rejoindre la branche",
    "en": "Join the branch",
    "es": "Unirse a la sucursal",
    "zgh": "ⴽⵛⵎ ⵖ ⴰⴼⵕⵄ"
  },
  "نبذة عن الفرع": {
    "fr": "À propos de la branche",
    "en": "About the branch",
    "es": "Acerca de la sucursal",
    "zgh": "ⵅⴼ ⵓⴼⵕⵄ"
  },
  "فرع مدينة طنجة": {
    "fr": "Branche de la ville de Tanger",
    "en": "Tangier city branch",
    "es": "Sucursal de la ciudad de Tánger",
    "zgh": "ⴰⴼⵕⵄ ⵏ ⵜⴰⵎⴷⵉⵏⵜ ⵏ ⵟⵟⴰⵏⵊⴰ"
  },
  "يعد فرع مدينة طنجة من الفروع النشطة للجمعية المغربية لهواة البحث والاستكشاف. ينظم الفرع أنشطة متنوعة تشمل الرحلات الاستكشافية والحملات البيئية والورشات التكوينية، بمشاركة واسعة من أعضاء الجمعية والمتطوعين. يسعى الفرع إلى ترسيخ قيم المواطنة وحماية البيئة ونشر ثقافة الاستكشاف العلمي بين شباب المدينة.": {
    "fr": "La branche de Tanger est l'une des branches actives de l'Association Marocaine des Amateurs de Recherche et d'Exploration. Elle organise des activités variées comprenant des expéditions d'exploration, des campagnes environnementales et des ateliers de formation, avec une large participation des membres et des bénévoles. La branche s'efforce d'enraciner les valeurs de la citoyenneté, de protéger l'environnement et de diffuser la culture de l'exploration scientifique parmi les jeunes de la ville.",
    "en": "The Tangier city branch is one of the active branches of the Moroccan Association of Research and Exploration Enthusiasts. The branch organizes a variety of activities including exploration trips, environmental campaigns and training workshops, with broad participation from association members and volunteers. The branch works to instil the values of citizenship, protect the environment and spread the culture of scientific exploration among the city's youth.",
    "es": "La sucursal de Tánger es una de las sucursales activas de la Asociación Marroquí de Aficionados a la Investigación y la Exploración. La sucursal organiza diversas actividades que incluyen expediciones de exploración, campañas medioambientales y talleres de formación, con una amplia participación de los miembros y voluntarios de la asociación. La sucursal se esfuerza por arraigar los valores de la ciudadanía, proteger el medio ambiente y difundir la cultura de la exploración científica entre los jóvenes de la ciudad.",
    "zgh": "ⴰⴼⵕⵄ ⵏ ⵜⴰⵎⴷⵉⵏⵜ ⵏ ⵟⵟⴰⵏⵊⴰ ⵉⴳⴰ ⵢⴰⵏ ⵣⴳ ⵉⴼⵕⵄⵏ ⵉⵅⴷⴷⵎⵏ ⵏ ⵜⵎⵣⴳⵉⴷⴰ ⵜⴰⵎⵖⵔⵉⴱⵉⵢⵜ ⵏ ⵉⵏⵎⵉⵏⴰⵢⵏ ⵏ ⵓⵎⴰⴷⴷⵓⵔ ⴷ ⵜⵎⵣⵣⴰⵍⵍⵉⵜ. ⵉⵙⴽⴰⵔ ⵓⴼⵕⵄ ⵉⵎⴰⵍⴰⵙⵏ ⵉⵎⴽⵏⴰⵍⵏ ⵢⵓⵎⴰⵏ ⵜⵉⵙⵓⴼⴰⵖⵉⵏ ⵜⵉⵎⵣⵣⵓⵍⵉⵏ, ⵜⵉⵎⵓⵔⵉⵏ ⵜⵉⵎⵥⵥⵉⴳⵉⵏ ⴷ ⵜⵉⵡⵡⵓⵔⴰ ⵜⵉⵙⴳⵎⴰⵏⵉⵏ, ⵙ ⵓⴷⴷⴰⵙ ⵉⵡⵙⵉⵔⵏ ⵏ ⵉⵏⴰⵎⵓⵔⵏ ⵏ ⵜⵎⵣⴳⵉⴷⴰ ⴷ ⵉⵎⴷⴷⴰⵡⵏ. ⵉⵙⵙⵀⵎⵔ ⵓⴼⵕⵄ ⵅⴼ ⵓⵙⵔⵙ ⵏ ⵉⵏⴰⵎⵓⵏⵙⵏ ⵏ ⵜⴰⵏⴰⵎⵓⵏⵜ, ⴰⵙⴷⴰⵔ ⵏ ⵜⴰⵡⴳⵏⴰ ⴷ ⵓⵙⴼⵍⵙ ⵏ ⵜⵎⵓⵙⵙⵏⴰ ⵏ ⵜⵎⵣⵣⴰⵍⵍⵉⵜ ⵜⴰⵙⵏⵎⵓⵔⵉⵏ ⴳⵔ ⵉⵎⵀⴰⵏⵏ ⵏ ⵜⵎⴷⵉⵏⵜ"
  },
