  "املأ النموذج التالي وسيتواصل معكم فريقنا في أقرب وقت.": {
    "fr": "Remplissez le formulaire suivant et notre équipe vous contactera dans les plus brefs délais.",
    "en": "Fill in the following form and our team will contact you as soon as possible.",
    "es": "Rellena el siguiente formulario y nuestro equipo se pondrá en contacto contigo lo antes posible.",
    "zgh": "ⵎⵏⵓ ⵜⴰⴼⵍⴰⵙⵜ ⴰⴷ ⵉⵣⴷⴰⵔⵏ ⴰⵏⵏ ⵜⵎⵙⴰⵔⴰ ⵜⴰⵔⴱⴱⵉⵄⵜ ⵏⵏⵖ ⴷ ⴰⵡⵏ ⴳ ⵉⵣⵎⵣⵉⵏ ⵉⵇⵇⵏⵉⵏ"
  },
  "فريقنا جاهز للرد على استفساراتكم من الإثنين إلى الجمعة. لا تترددوا في التواصل معنا عبر أي وسيلة تناسبكم.": {
    "fr": "Notre équipe est prête à répondre à vos demandes du lundi au vendredi. N'hésitez pas à nous contacter par le moyen qui vous convient.",
    "en": "Our team is ready to answer your inquiries from Monday to Friday. Don't hesitate to contact us through whatever means suits you.",
    "es": "Nuestro equipo está listo para responder a tus consultas de lunes a viernes. No dudes en contactarnos por el medio que prefieras.",
    "zgh": "ⵜⴰⵔⴱⴱⵉⵄⵜ ⵏⵏⵖ ⵎⵓⴷⵉⵢⴰ ⵉ ⵓⵊⴰⵡⴰⴱ ⵏ ⵉⵙⴰⵇⵙⵉⵜⵏ ⵏⵏⵓⵏ ⵣⴳ ⵡⴰⵢⵏⴰⵙ ⴰⵔ ⵊⵉⵎⵄⴰ. ⵓⵔ ⵜⵙⵙⴽⵓⵙⵓ ⴰⴷ ⵜⵎⵙⴰⵔⴰⵎ ⴷ ⵏⵏⵖ ⵙ ⵢⴰⵜ ⵜⵖⴰⵔⴰⵙⵜ ⵏⵏⴰ ⵏⵏ ⵜⵥⵍⵎⵏ"
  },
